const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];let activeChat='',allConvs=[];
async function api(url,opts={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...(opts.headers||{})},credentials:'same-origin',...opts});const j=await r.json().catch(()=>({}));if(r.status===401){if(!location.pathname.endsWith('/login.html'))location.replace('/login.html?reason=session');throw new Error(j.error||T('js.session_required','Sesión requerida'))}if(!r.ok)throw new Error(j.error||T('js.server_error','Error de servidor'));return j}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2500)}
const T=(k,f)=>(window.wtT&&window.wtT(k))||f;
const STAGE_MAP={'Nuevo':'js.stage_new','Contactado':'js.stage_contacted','Interesado':'js.stage_interested','Calificado':'js.stage_qualified','Cotización':'js.stage_quote','Negociación':'js.stage_negotiation','Ganado':'js.stage_won','Perdido':'js.stage_lost'};
function stageLabel(s){return STAGE_MAP[s]?T(STAGE_MAP[s],s):s}
const APPT_STATUS_MAP={'Programada':'js.appt_scheduled','Confirmada':'js.appt_confirmed','Completada':'js.appt_completed','Cancelada':'js.appt_cancelled','No asistió':'js.appt_noshow'};
function apptStatusLabel(s){return APPT_STATUS_MAP[s]?T(APPT_STATUS_MAP[s],s):s}
function wtTitleFor(v,part){return (window.wtTitle&&window.wtTitle(v,part))||''}
