async function loadDashboard(){const [d,h,c]=await Promise.all([api('/api/dashboard'),api('/api/channels/health'),api('/api/channels/connections')]);$('#stats').innerHTML=[[T('js.stat_conversations','Conversaciones'),d.conversations],[T('js.stat_messages','Mensajes'),d.messages],[T('js.stat_unread','Sin leer'),d.unread],[T('js.stat_crm_contacts','Contactos CRM'),d.contacts],[T('js.stat_opportunities','Oportunidades'),d.open_opportunities],[T('js.stat_pipeline_value','Valor pipeline'),'$'+Number(d.pipeline_value||0).toLocaleString()],[T('js.stat_products','Productos'),d.products||0],[T('js.stat_upcoming_appts','Citas próximas'),d.appointments||0]].map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('');const connected=h.states.connected||0;$('#statusPill').textContent=connected?`${connected} ${T('js.channels_connected_count','canal(es) conectado(s)')}`:T('js.channels_pending','Canales pendientes');const by=t=>c.connections.filter(x=>x.type===t&&x.status==='connected').length;const cs=T('js.connected_suffix','conectado(s)');$('#channelSummary').innerHTML=`<p>WhatsApp: <b>${by('whatsapp_qr')} ${cs}</b></p><p>Telegram: <b>${by('telegram')} ${cs}</b></p><p>Messenger: <b>${by('messenger')} ${cs}</b></p><p>${T('js.isolation_label','Aislamiento')}: <b>${T('js.isolation_value','tenant + conexión')}</b></p>`}
async function loadConvs(){allConvs=await api('/api/conversations');renderConvs(allConvs)}function renderConvs(xs){$('#convList').innerHTML=xs.map(c=>`<div class="conv ${c.chat_jid===activeChat?'active':''}" data-chat="${c.chat_jid}"><div class="top"><b>${esc(c.name||c.phone)}</b><span class="badge ${c.channel}">${c.channel==='telegram'?'TG':(c.channel==='messenger'?'MS':'WA')}</span></div><small>${esc(c.last_text||'')}</small>${c.unread?`<b>${c.unread} ${T('js.new_messages','nuevos')}</b>`:''}</div>`).join('');$$('.conv').forEach(x=>x.onclick=()=>openChat(x.dataset.chat))}
$('#searchConv').oninput=e=>renderConvs(allConvs.filter(c=>(c.name+c.phone+c.last_text).toLowerCase().includes(e.target.value.toLowerCase())));
async function openChat(chat){activeChat=chat;const c=allConvs.find(x=>x.chat_jid===chat);$('#chatHead').textContent=(c?.name||c?.phone||chat)+' · '+(c?.channel||'');await api('/api/read',{method:'POST',body:JSON.stringify({chat})});const ms=await api('/api/messages?chat='+encodeURIComponent(chat));$('#messages').innerHTML=ms.map(m=>`<div class="msg ${m.direction==='out'?'out':''}">${esc(m.text)}<small>${new Date(m.timestamp).toLocaleString()} · ${m.status}</small></div>`).join('');$('#messages').scrollTop=$('#messages').scrollHeight;renderConvs(allConvs)}
$('#sendForm').onsubmit=async e=>{e.preventDefault();if(!activeChat)return toast(T('js.select_conversation','Selecciona una conversación'));const text=$('#messageText').value.trim();if(!text)return;try{await api('/api/send',{method:'POST',body:JSON.stringify({chat:activeChat,text})});$('#messageText').value='';await openChat(activeChat);await loadConvs()}catch(e){toast(e.message)}};
