async function loadChannels(){
  const d=await api('/api/channels/connections'),h=await api('/api/channels/health');
  $('#channelLimit').textContent=`${d.connections.length} ${T('js.of_connections','de')} ${d.max_total} ${T('js.connections_word','conexiones')}`;
  $('#channelHealth').innerHTML=[[T('js.stat_active','Conectadas'),h.states.connected||0],[T('js.stat_waiting_qr','Esperando QR'),h.states.waiting_qr||0],[T('js.stat_with_error','Con error'),h.states.error||0],[T('js.stat_isolated_msgs','Mensajes aislados'),h.messages||0]].map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('');
  $('#channelConnections').innerHTML=d.connections.length?d.connections.map(c=>`<article class="card"><div class="top"><span class="badge ${c.type}">${c.type==='whatsapp_qr'?'WhatsApp':c.type==='telegram'?'Telegram':'Messenger'}</span><span class="pill">${esc(c.status)}</span></div><h3>${esc(c.name)}</h3><p>${c.external_account_id?`${T('js.account_label','Cuenta')}: <b>${esc(c.external_account_id)}</b>`:T('js.not_linked','Aún no vinculada')}</p><small>${T('js.assigned_agent','Agente asignado')}: ${c.assigned_agent_id||T('js.main_agent','principal')} · ID ${c.id}</small>${c.last_error?`<div class="notice">${esc(c.last_error)}</div>`:''}<div id="qrbox-${c.id}"></div><div class="actions"><button onclick='connectTenantChannel(${JSON.stringify(c)})'>${c.status==='connected'?T('js.reconfigure','Reconfigurar'):T('js.connect','Conectar')}</button><button class="secondary" onclick="pauseTenantChannel(${c.id})">${T('js.pause','Pausar')}</button><button class="danger" onclick="deleteTenantChannel(${c.id})">${T('js.delete','Eliminar')}</button></div></article>`).join(''):`<p>${T('js.no_connections','No hay conexiones. Crea el primer canal de este espacio.')}</p>`;
}
