$('#newChannel').onclick=()=>modal(`<h2>${T('js.new_isolated_conn_title','Nueva conexión aislada')}</h2><label>${T('js.type_label','Tipo')}<select id="ccType"><option value="whatsapp_qr">WhatsApp QR</option><option value="telegram">Telegram Bot</option><option value="messenger">Facebook Messenger</option></select></label><label>${T('js.name_label','Nombre')}<input id="ccName" placeholder="${T('js.channel_name_ph','Ej. WhatsApp Ventas')}"></label><label>${T('js.agent_id_label','Agente ID')}<input id="ccAgent" type="number" min="0" value="0"></label><div class="notice">${T('js.channel_limit_notice','El backend valida el límite total y el máximo por tipo de tu plan.')}</div><div class="actions"><button type="button" id="saveChannel">${T('js.create','Crear')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='saveChannel')return;document.removeEventListener('click',h);try{await api('/api/channels/connections',{method:'POST',body:JSON.stringify({type:$('#ccType').value,name:$('#ccName').value,assigned_agent_id:Number($('#ccAgent').value||0)})});$('#modal').close();loadChannels();toast(T('js.connection_created','Conexión creada'))}catch(err){toast(err.message)}});
window.connectTenantChannel=async c=>{
 if(c.type==='whatsapp_qr'){await api('/api/channels/action',{method:'POST',body:JSON.stringify({id:c.id,action:'connect',agent_id:c.assigned_agent_id||0})});toast(T('js.generating_qr','Generando QR exclusivo'));pollTenantQR(c.id);return}
 return; // reemplazado por el formulario profesional V13.1
};
