let marketingLimits={},campaignAIPlan='';
$$('.growth-tabs button').forEach(b=>b.onclick=()=>{$$('.growth-tabs button,.growth-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#growth-'+b.dataset.growth).classList.add('active');const k=b.dataset.growth;if(k==='calendar')loadMarketingContent();if(k==='creatives')loadCreatives();if(k==='forms')loadLeadForms();if(k==='leads')loadMarketingLeads()});
async function loadMarketing(){
 const [o,cs]=await Promise.all([api('/api/marketing/overview'),api('/api/marketing/campaigns')]);marketingLimits=o.limits||{};
 $('#marketingPlan').textContent=`${marketingLimits.plan||'free'} · ${marketingLimits.organic?T('js.organic_label','Orgánico'):''}${marketingLimits.paid?' + '+T('js.paid_label','Pagado'):''}${marketingLimits.combined?' + '+T('js.combined_label','Combinado'):''}`;
 $('#marketingStats').innerHTML=[[T('js.stat_campaigns','Campañas'),o.campaigns],[T('js.stat_scheduled','Programados'),o.scheduled],[T('js.stat_leads','Leads'),o.leads],[T('js.stat_forms','Formularios'),o.forms],[T('js.stat_creatives','Creativos'),o.creatives]].map(x=>`<div class="stat"><b>${x[1]||0}</b><small>${x[0]}</small></div>`).join('');
 renderCampaigns(cs);
}
function renderCampaigns(xs){$('#campaignsGrid').innerHTML=xs.length?xs.map(x=>`<article class="product-card campaign-card"><span class="campaign-mode mode-${x.mode}">${esc(x.mode)}</span><b>${esc(x.name)}</b><p>${esc(x.objective)} · ${esc(x.product||T('js.no_product','Sin producto'))}</p><small>${esc(x.platforms)} → ${esc(x.destination)}</small><p><b>${T('js.budget_label','Presupuesto')}:</b> ${Number(x.budget_total||0).toLocaleString()} USDT</p><div class="actions"><button class="secondary" onclick="campaignDetails(${x.id})">${T('js.view_strategy','Ver estrategia')}</button><button class="danger" onclick="deleteCampaign(${x.id})">${T('js.delete','Eliminar')}</button></div></article>`).join(''):`<p>${T('js.no_campaigns','No hay campañas. Crea la primera con el asistente de IA.')}</p>`}
$('#generateCampaign').onclick=async()=>{const f=$('#campaignWizard'),d=Object.fromEntries(new FormData(f));d.days=14;const b=$('#generateCampaign');b.disabled=true;$('#campaignAIPlan').textContent=T('js.creating_strategy','Creando estrategia…');try{const x=await api('/api/marketing/generate',{method:'POST',body:JSON.stringify(d)});campaignAIPlan=x.plan;$('#campaignAIPlan').textContent=x.plan}catch(e){$('#campaignAIPlan').textContent=e.message}finally{b.disabled=false}};
$('#campaignWizard').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.budget_daily=Number(d.budget_daily||0);d.budget_total=Number(d.budget_total||0);d.ai_plan=campaignAIPlan;try{await api('/api/marketing/campaigns',{method:'POST',body:JSON.stringify(d)});e.target.reset();campaignAIPlan='';$('#campaignAIPlan').textContent=T('js.campaign_saved_desc','Campaña guardada. Puedes crear contenido y formularios relacionados.');toast(T('js.campaign_created','Campaña creada'));loadMarketing()}catch(e){toast(e.message)}};
window.deleteCampaign=async id=>{}; // redefinido en V13.1
window.campaignDetails=async id=>{const xs=await api('/api/marketing/campaigns'),x=xs.find(a=>a.id===id);modal(`<h2>${esc(x?.name||T('js.campaign_word','Campaña'))}</h2><div class="growth-plan">${esc(x?.ai_plan||T('js.no_ai_strategy','Sin estrategia IA guardada'))}</div><button value="cancel">${T('js.close','Cerrar')}</button>`)};
async function loadMarketingContent(){const xs=await api('/api/marketing/content');$('#contentCalendar').innerHTML=xs.length?xs.map(x=>`<div class="calendar-item"><div class="date">${x.scheduled_at?new Date(x.scheduled_at).toLocaleString():T('js.not_scheduled','Sin programar')}</div><b>${esc(x.title||x.format)}</b><p>${esc(x.body)}</p><small>${esc(x.platform)} · ${esc(x.format)} · ${esc(x.status)}</small><div><button class="danger" onclick="deleteContent(${x.id})">${T('js.delete','Eliminar')}</button></div></div>`).join(''):`<p>${T('js.no_scheduled_content','No hay contenido programado.')}</p>`}
$('#newContent').onclick=()=>modal(`<h2>${T('js.new_content_title','Nuevo contenido')}</h2><label>${T('js.campaign_id_label','Campaña ID')}<input id="ctCampaign" type="number" value="0"></label><div class="grid2"><label>${T('js.platform_label','Plataforma')}<select id="ctPlatform"><option>facebook</option><option>instagram</option><option>messenger</option></select></label><label>${T('js.format_label','Formato')}<select id="ctFormat"><option>post</option><option>reel</option><option>story</option><option>carousel</option></select></label></div><label>${T('js.title_label','Título')}<input id="ctTitle"></label><label>${T('js.content_label','Contenido')}<textarea id="ctBody" rows="6"></textarea></label><label>CTA<input id="ctCTA" placeholder="${T('js.cta_ph','Escríbenos por WhatsApp')}"></label><label>${T('js.schedule_label','Programar')}<input id="ctSchedule" type="datetime-local"></label><div class="actions"><button type="button" id="saveContent">${T('js.save','Guardar')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div>`);document.addEventListener('click',async function h(ev){if(ev.target?.id!=='saveContent')return;document.removeEventListener('click',h);const raw=$('#ctSchedule').value;await api('/api/marketing/content',{method:'POST',body:JSON.stringify({campaign_id:Number($('#ctCampaign').value||0),platform:$('#ctPlatform').value,format:$('#ctFormat').value,title:$('#ctTitle').value,body:$('#ctBody').value,cta:$('#ctCTA').value,scheduled_at:raw?new Date(raw).toISOString():'',status:raw?'scheduled':'draft'})});$('#modal').close();loadMarketingContent();toast(T('js.content_saved','Contenido guardado'))});
window.deleteContent=async id=>{await api('/api/marketing/content?id='+id,{method:'DELETE'});loadMarketingContent()};
async function loadCreatives(){const xs=await api('/api/marketing/creatives');$('#creativeGrid').innerHTML=xs.length?xs.map(x=>`<article class="product-card"><b>${esc(x.name)}</b><p>${esc(x.kind)}</p>${x.url?`<a href="${esc(x.url)}" target="_blank">${T('js.open_resource','Abrir recurso')}</a>`:''}<small>${esc(x.notes)}</small></article>`).join(''):`<p>${T('js.no_creatives','No hay creativos.')}</p>`}
$('#newCreative').onclick=()=>modal(`<h2>${T('js.add_creative_title','Agregar creativo')}</h2><label>${T('js.name_label','Nombre')}<input id="crName"></label><label>${T('js.type_label','Tipo')}<select id="crKind"><option>image</option><option>video</option><option>copy</option><option>document</option></select></label><label>${T('js.resource_url_label','URL del recurso')}<input id="crURL" placeholder="https://..."></label><label>${T('js.notes_label','Notas')}<textarea id="crNotes"></textarea></label><div class="actions"><button type="button" id="saveCreative">${T('js.save','Guardar')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div>`);document.addEventListener('click',async function h2(ev){if(ev.target?.id!=='saveCreative')return;document.removeEventListener('click',h2);await api('/api/marketing/creatives',{method:'POST',body:JSON.stringify({name:$('#crName').value,kind:$('#crKind').value,url:$('#crURL').value,notes:$('#crNotes').value})});$('#modal').close();loadCreatives();toast(T('js.creative_saved','Creativo guardado'))});
async function loadLeadForms(){const xs=await api('/api/marketing/forms');$('#leadFormsGrid').innerHTML=xs.length?xs.map(x=>`<article class="product-card"><b>${esc(x.name)}</b><p>${esc(x.headline)}</p><div class="public-link">${location.origin}/f/${x.tenant_id}/${x.slug}</div><button onclick="navigator.clipboard.writeText('${location.origin}/f/${x.tenant_id}/${x.slug}');toast('${T('js.link_copied','Enlace copiado')}')">${T('js.copy_link','Copiar enlace')}</button></article>`).join(''):`<p>${T('js.no_forms','No hay formularios.')}</p>`}
$('#newLeadForm').onclick=()=>modal(`<h2>${T('js.new_form_title','Nuevo formulario / landing')}</h2><label>${T('js.name_label','Nombre')}<input id="lfName"></label><label>${T('js.slug_label','Slug')}<input id="lfSlug" placeholder="valoracion-gratis"></label><label>${T('js.public_title_label','Título público')}<input id="lfHeadline"></label><label>${T('js.description_label','Descripción')}<textarea id="lfDesc"></textarea></label><label>${T('js.consent_text_label','Texto de consentimiento')}<textarea id="lfConsent">${T('js.consent_default_text','Autorizo el tratamiento de mis datos para recibir información relacionada con esta solicitud.')}</textarea></label><label>${T('js.thanks_message_label','Mensaje de gracias')}<textarea id="lfThanks">${T('js.thanks_default_text','Gracias. Pronto te contactaremos.')}</textarea></label><div class="actions"><button type="button" id="saveLeadForm">${T('js.create','Crear')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div>`);document.addEventListener('click',async function h3(ev){if(ev.target?.id!=='saveLeadForm')return;document.removeEventListener('click',h3);await api('/api/marketing/forms',{method:'POST',body:JSON.stringify({name:$('#lfName').value,slug:$('#lfSlug').value,headline:$('#lfHeadline').value,description:$('#lfDesc').value,consent_text:$('#lfConsent').value,thank_you:$('#lfThanks').value})});$('#modal').close();loadLeadForms();toast(T('js.form_published','Formulario publicado'))});
